//! Spec 0059 T13 (R56): the pure helpers of `dominio inject` give the TS answer for every row of
//! `fixtures/tools_tables.json`, generated by `scripts/js/rust-oracle/tools-tables.mjs`. Each test
//! walks a whole table and reports every mismatching row at once.
// Covers: R56

use std::cmp::Ordering;

use navori_core::collate::compare_ascii;
use navori_core::js_json;
use navori_core::render::context::Lang;
use navori_core::workspace::dominio::{Status, inject_strings, parse_entry};
use navori_core::workspace::registry::validate;
use serde_json::Value;

fn table() -> Value {
    serde_json::from_str(include_str!("fixtures/tools_tables.json")).unwrap_or(Value::Null)
}

fn rows<'a>(table: &'a Value, key: &str) -> &'a [Value] {
    let rows = table[key].as_array().map_or(&[][..], Vec::as_slice);
    assert!(!rows.is_empty(), "table {key} is empty");
    rows
}

#[test]
fn la_colacion_ascii_ordena_como_localecompare() {
    let table = table();
    let order: Vec<char> = table["collation"]["order"]
        .as_str()
        .unwrap_or_default()
        .chars()
        .collect();
    assert_eq!(order.len(), 95);
    let mut failures = Vec::new();
    for pair in order.windows(2) {
        let (a, b) = (pair[0].to_string(), pair[1].to_string());
        if compare_ascii(&a, &b) != Some(Ordering::Less) {
            failures.push(format!("{a:?} < {b:?}"));
        }
    }
    for row in rows(&table["collation"], "pairs") {
        let (a, b) = (
            row["a"].as_str().unwrap_or_default(),
            row["b"].as_str().unwrap_or_default(),
        );
        let expected = match row["sign"].as_i64() {
            Some(-1) => Ordering::Less,
            Some(0) => Ordering::Equal,
            _ => Ordering::Greater,
        };
        if compare_ascii(a, b) != Some(expected) {
            failures.push(format!(
                "{a:?} vs {b:?}: {:?}, TS {expected:?}",
                compare_ascii(a, b)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn las_entradas_de_dominio_se_leen_como_readentry() {
    let table = table();
    let mut failures = Vec::new();
    for row in rows(&table, "entries") {
        let id = row["id"].as_str().unwrap_or_default();
        let raw = row["raw"].as_str().unwrap_or_default();
        let Ok(entry) = parse_entry(id, raw) else {
            failures.push(format!("{id}: delegated"));
            continue;
        };
        let applies_to = match &row["appliesTo"] {
            Value::String(all) if all == "all" => None,
            Value::Array(items) => Some(
                items
                    .iter()
                    .map(|v| v.as_str().unwrap_or_default().to_owned())
                    .collect(),
            ),
            _ => Some(vec!["<bad row>".to_owned()]),
        };
        let status = match row["status"].as_str() {
            Some("deprecated") => Status::Deprecated,
            Some("superseded") => Status::Superseded,
            _ => Status::Canonical,
        };
        if entry.title != row["title"].as_str().unwrap_or_default()
            || entry.applies_to != applies_to
            || entry.status != status
            || entry.summary != row["summary"].as_str().unwrap_or_default()
        {
            failures.push(format!("{id}: {entry:?}\n  TS {row}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn el_esquema_de_workspace_acepta_lo_mismo_que_zod() {
    let table = table();
    let mut failures = Vec::new();
    for row in rows(&table, "workspaces") {
        let input = row["input"].to_string();
        let Some(parsed) = js_json::parse(&input) else {
            failures.push(format!("{input}: unparsed"));
            continue;
        };
        let got = validate(&parsed);
        let expected = row["valid"].as_bool().unwrap_or_default().then(|| {
            (
                row["language"].as_str().map(str::to_owned),
                row["repoPaths"]
                    .as_array()
                    .map(|paths| {
                        paths
                            .iter()
                            .map(|p| p.as_str().unwrap_or_default().to_owned())
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default(),
            )
        });
        let got_pair = got
            .as_ref()
            .ok()
            .and_then(Option::as_ref)
            .map(|w| (w.language.clone(), w.repo_paths.clone()));
        if got.is_err() || got_pair != expected {
            failures.push(format!("{input}: {got:?}, TS {expected:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn los_textos_de_inject_son_los_del_ts() {
    let table = table();
    let mut failures = Vec::new();
    for row in rows(&table, "inject") {
        let lang = if row["lang"] == "en" {
            Lang::En
        } else {
            Lang::Es
        };
        let (header, hint) = inject_strings(lang, "ws-name");
        if header != row["header"].as_str().unwrap_or_default()
            || hint != row["hint"].as_str().unwrap_or_default()
        {
            failures.push(format!("{lang:?}: {header} / {hint}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
